import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed, collectProgressTelemetry } from './src/workspace.js';

const deferred = () => { let resolve; return { promise: new Promise(r => { resolve = r; }), resolve }; };

{
  const shown = [], history = [], transport = [];
  const feed = createProgressFeed({ initialPacket: 'warm' });
  const workspace = createTransferWorkspace({
    transport: event => transport.push(event.attemptId), onCancel: () => {}, record: () => {}, showQueued: () => {},
    recordProgress: event => history.push(event), showProgress: event => shown.push(event),
  });
  workspace.select({ id: 'one', progressFeed: feed });
  feed.emit('next');
  assert.deepEqual(shown.map(x => x.frame), ['warm', 'next']);
  assert.deepEqual(history.map(x => x.frame), ['warm', 'next']);
  assert.deepEqual(transport, [1]);
}

{
  const jobs = new Map(), shown = [], history = [];
  const feed = createProgressFeed({ decode(packet) { const job = deferred(); jobs.set(packet, job); return job.promise; } });
  const workspace = createTransferWorkspace({
    transport: () => {}, onCancel: () => {}, record: () => {}, showQueued: () => {},
    recordProgress: event => history.push(event), showProgress: event => shown.push(event),
  });
  workspace.select({ id: 'two', progressFeed: feed });
  feed.emit('older');
  feed.emit('newer');
  jobs.get('newer').resolve('newer-decoded');
  await Promise.resolve();
  jobs.get('older').resolve('older-decoded');
  await Promise.resolve();
  assert.deepEqual(history.map(x => x.frame), ['newer-decoded', 'older-decoded']);
  assert.deepEqual(shown.map(x => x.frame), ['newer-decoded']);
}

{
  const jobs = [], shown = [], history = [];
  const feed = createProgressFeed({ decode(packet) { const job = deferred(); jobs.push([packet, job]); return job.promise; } });
  const workspace = createTransferWorkspace({
    transport: () => {}, onCancel: () => {}, record: () => {}, showQueued: () => {},
    recordProgress: event => history.push(event), showProgress: event => shown.push(event),
  });
  workspace.select({ id: 'three', progressFeed: feed });
  feed.emit('old');
  workspace.retry();
  feed.emit('new');
  jobs.find(([packet]) => packet === 'new')[1].resolve('new-decoded');
  await Promise.resolve();
  jobs.find(([packet]) => packet === 'old')[1].resolve('old-decoded');
  await Promise.resolve();
  assert.deepEqual(shown.map(x => [x.attemptId, x.frame]), [[2, 'new-decoded']]);
  assert.deepEqual(history.map(x => [x.attemptId, x.frame]), [[2, 'new-decoded'], [1, 'old-decoded']]);
}

{
  const deltas = [];
  const feed = createProgressFeed({ initialPacket: 'cached' });
  const stop = collectProgressTelemetry(feed, value => deltas.push(value));
  feed.emit('live');
  stop();
  assert.deepEqual(deltas, ['live']);
}

{
  let transports = 0, cancels = 0;
  const feed = createProgressFeed({ initialPacket: 'warm' });
  let workspace;
  workspace = createTransferWorkspace({
    transport: () => { transports++; }, onCancel: () => { cancels++; }, record: () => {}, showQueued: () => {},
    showProgress: () => workspace.hide(),
  });
  workspace.select({ id: 'four', progressFeed: feed });
  assert.equal(transports, 0);
  assert.equal(cancels, 1);
  assert.equal(workspace.snapshot().visitId, null);
}

console.log('progress regression checks passed');
